-- Project file schema (SQLite). One .proj file per project.
-- Times are integer microseconds. IDs are UUIDv7 text generated by the engine.
-- Run with: PRAGMA foreign_keys = ON;

PRAGMA user_version = 1;

create table meta (
  key   text primary key,
  value text not null
);
-- keys: app_version, created_with, schema_version

create table project (
  id            text primary key,
  name          text not null,
  aspect_ratio  text not null,              -- '16:9', '9:16', '1:1', '4:5', 'custom'
  width         integer not null check (width > 0),
  height        integer not null check (height > 0),
  fps_num       integer not null check (fps_num > 0),
  fps_den       integer not null default 1 check (fps_den > 0),
  sample_rate   integer not null default 48000,
  created_at    integer not null,           -- unix seconds, UTC
  updated_at    integer not null
);

create table media_item (
  id            text primary key,
  path          text not null,              -- absolute path; may go missing
  kind          text not null check (kind in ('video','audio','image')),
  duration_us   integer,                    -- null for images
  width         integer,
  height        integer,
  fps_num       integer,
  fps_den       integer,
  has_audio     integer not null default 0 check (has_audio in (0,1)),
  codec         text,
  file_size     integer,
  file_mtime    integer,                    -- to detect changed files
  is_vfr        integer not null default 0 check (is_vfr in (0,1)),
  proxy_path    text,                       -- low-res intra-frame copy, nullable
  proxy_state   text not null default 'none'
                check (proxy_state in ('none','queued','building','ready','failed')),
  asset_id      text,                       -- set when it came from the bundled stock pack
  status        text not null default 'ok' check (status in ('ok','missing','unsupported')),
  created_at    integer not null
);
create index media_item_path on media_item (path);

create table track (
  id        text primary key,
  kind      text not null check (kind in ('video','audio','text','effect','sticker')),
  position  integer not null,               -- stacking order; higher = on top for video
  locked    integer not null default 0 check (locked in (0,1)),
  muted     integer not null default 0 check (muted in (0,1)),
  hidden    integer not null default 0 check (hidden in (0,1))
);
create unique index track_position on track (kind, position);

create table clip (
  id              text primary key,
  track_id        text not null references track(id) on delete cascade,
  media_item_id   text references media_item(id) on delete restrict,  -- null for text/effect clips
  start_us        integer not null check (start_us >= 0),   -- position on the timeline
  duration_us     integer not null check (duration_us > 0),
  in_us           integer not null default 0,               -- offset into the source
  speed           real not null default 1.0 check (speed > 0),
  speed_curve     text,                                     -- json, null = constant
  pos_x           real not null default 0,
  pos_y           real not null default 0,
  scale           real not null default 1,
  rotation        real not null default 0,
  opacity         real not null default 1 check (opacity between 0 and 1),
  blend_mode      text not null default 'normal',
  crop            text,                                     -- json {l,t,r,b}
  mirror          integer not null default 0 check (mirror in (0,1)),
  reverse         integer not null default 0 check (reverse in (0,1)),
  volume          real not null default 1 check (volume >= 0),
  fade_in_us      integer not null default 0 check (fade_in_us >= 0),
  fade_out_us     integer not null default 0 check (fade_out_us >= 0),
  mask            text,                                     -- json, null = none
  created_at      integer not null
);
create index clip_track_start on clip (track_id, start_us);
create index clip_media on clip (media_item_id);

create table text_item (
  clip_id    text primary key references clip(id) on delete cascade,
  content    text not null,
  font       text not null,
  size       real not null check (size > 0),
  colour     text not null,                 -- #RRGGBBAA
  align      text not null default 'center' check (align in ('left','center','right')),
  style      text                           -- json: outline, shadow, background, spacing
);

create table adjustment (
  clip_id         text primary key references clip(id) on delete cascade,
  basic           text,                     -- json: brightness, contrast, saturation, temperature, ...
  hsl             text,                     -- json
  curves          text,                     -- json
  filter_id       text,                     -- id of a built-in filter
  filter_strength real not null default 1 check (filter_strength between 0 and 1)
);

create table keyframe (
  id        text primary key,
  clip_id   text not null references clip(id) on delete cascade,
  property  text not null,                  -- 'pos_x','scale','rotation','opacity','volume',...
  time_us   integer not null check (time_us >= 0),   -- relative to clip start
  value     real not null,
  easing    text not null default 'linear'
);
create unique index keyframe_unique on keyframe (clip_id, property, time_us);

create table effect (
  id        text primary key,
  clip_id   text not null references clip(id) on delete cascade,
  kind      text not null,                  -- built-in effect id (blur, vignette, ...)
  params    text not null default '{}',
  position  integer not null default 0      -- order in the effect stack
);
create index effect_clip on effect (clip_id, position);

create table transition (
  id           text primary key,
  clip_a_id    text not null references clip(id) on delete cascade,
  clip_b_id    text not null references clip(id) on delete cascade,
  kind         text not null,               -- 'dissolve','slide','wipe','zoom','blur','fade_black'
  duration_us  integer not null check (duration_us > 0),
  params       text not null default '{}',
  check (clip_a_id <> clip_b_id)
);
create unique index transition_pair on transition (clip_a_id, clip_b_id);

create table marker (
  id       text primary key,
  time_us  integer not null check (time_us >= 0),
  label    text not null default ''
);

-- Undo/redo: each user action is one row. Payload holds the forward and inverse operations.
create table undo_log (
  id        integer primary key autoincrement,
  label     text not null,
  forward   text not null,                  -- json
  inverse   text not null,                  -- json
  applied   integer not null default 1 check (applied in (0,1)),
  created_at integer not null
);

